1: /* ==========================================================================
2:    Phase E3 weather surfaces, the --wx- token namespace
3:    (docs/research.md palette table, "New tokens live in a --wx- namespace
4:    next to --rp and --rv so the report and Money River files never change").
5: 
6:    The seven state tokens, one per weather state in canonical order:
7: 
8:      wx-clear     #56B4E9   sky blue (Okabe-Ito), calm and no shortfall
9:      wx-cloudy    #46617c   cloud slate, long runway with a spending gap
10:      wx-overcast  #2f4257   deep slate, the darker sibling of cloudy
11:      wx-rain      #2f7f7c   water lit, spending driven 3.0 to 11.9 months
12:      wx-drought   #d97b3f   drought orange, income covers 65 percent or less
13:      wx-storm     #ff6a4d   storm vermillion, runway under 3.0 months
14:      wx-flood     #10333f   water deep, buffer depleted or runway at 0.0
15: 
16:    Plus the two grounds every surface sits on: wx-grounds #070c18 (the
17:    archival navy, same value as --rp-void but read from its own token so
18:    this file never depends on --rp-) and wx-parchment #e9e0c9 for text.
19: 
20:    Soft tints (each state color at 26 percent over wx-grounds) carry every
21:    printed label, so measured contrast for parchment text stays above
22:    WCAG AA on all seven cells (worst case 9.3 to 1 on wx-clear-soft).
23:    Solid state colors are used for tile fills, swatches, and rules only,
24:    where no small text sits on them.
25: 
26:    The E3 strip slots do not use these state colors: they read the five
27:    verdict bands through their tailwind class and currentColor (see the
28:    .wx-slot rule below), so the badge and the strip share one source of
29:    band color.
30: 
31:    Motion in this file is gated behind prefers-reduced-motion:
32:    no-preference, matching src/index.css, which also zeroes animation
33:    durations globally under prefers-reduced-motion: reduce.
34:    ========================================================================== */
35: 
36: :root {
37:   /* The seven state colors. */
38:   --wx-clear: #56b4e9;
39:   --wx-cloudy: #46617c;
40:   --wx-overcast: #2f4257;
41:   --wx-rain: #2f7f7c;
42:   --wx-drought: #d97b3f;
43:   --wx-storm: #ff6a4d;
44:   --wx-flood: #10333f;
45: 
46:   /* Grounds and text. */
47:   --wx-grounds: #070c18;
48:   --wx-parchment: #e9e0c9;
49:   --wx-rule: rgba(233, 224, 201, 0.24);
50:   --wx-text-dim: rgba(233, 224, 201, 0.74);
51:   --wx-text-faint: rgba(233, 224, 201, 0.54);
52: 
53:   /* Soft tints for any surface that prints text on a state color. */
54:   --wx-clear-soft: #1c384e;
55:   --wx-cloudy-soft: #172232;
56:   --wx-overcast-soft: #111a28;
57:   --wx-rain-soft: #112a32;
58:   --wx-drought-soft: #3e2922;
59:   --wx-storm-soft: #482426;
60:   --wx-flood-soft: #091622;
61: 
62:   /* Utility, deliberately local so nothing here reaches into --rp-. */
63:   --wx-font-display: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas,
64:     "Liberation Mono", monospace;
65:   --wx-font-body: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
66:   --wx-radius: 4px;
67: }
