28: export function formatDeciMonths(deciMonths: number, state: RunwayState): string {
29:   if (state === 'no_shortfall') {
30:     return '120+ months'
31:   }
32:   if (state === 'buffer_depleted') {
33:     return '0.0 months'
34:   }
35:   if (!Number.isFinite(deciMonths)) {
36:     return 'n/a months'
37:   }
38:   return `${(deciMonths / 10).toFixed(1)} months`
39: }
